    front = parse(head) ?? {};
  } catch (error) {
    problems.push(`frontmatter: ${error.message.split('\n')[0]}`);
  }
  if (!front.title) problems.push('frontmatter: no title');
  if (!front.description) problems.push('frontmatter: no description');

